<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$pageTitle='Nova encomenda';$clients=$pdo->query('SELECT id,nome FROM clientes WHERE ativo=1 ORDER BY nome')->fetchAll();$products=$pdo->query('SELECT id,nome,preco FROM produtos WHERE ativo=1 ORDER BY nome')->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$cid=(int)$_POST['cliente_id'];$obs=trim($_POST['observacoes']??'');$pids=$_POST['produto_id']??[];$qtys=$_POST['quantidade']??[];$sub=0;$items=[];foreach($pids as $k=>$pid){$pid=(int)$pid;$q=number_value($qtys[$k]??0);if($pid&&$q>0){$st=$pdo->prepare('SELECT id,nome,preco FROM produtos WHERE id=? AND ativo=1');$st->execute([$pid]);$p=$st->fetch();if($p){$items[]=[(int)$p['id'],$q,(float)$p['preco'],$q*(float)$p['preco']];$sub+=$q*(float)$p['preco'];}}}if(!$cid)$error='Selecione um cliente.';elseif(!$items)$error='Adicione pelo menos um produto.';else{$pdo->beginTransaction();try{$num=next_number('ENC','encomendas');$pdo->prepare("INSERT INTO encomendas(numero,cliente_id,usuario_id,origem,data_hora,subtotal,desconto,total,status,observacoes) VALUES(?,?,?,?,?,?,?,?,?,?)")->execute([$num,$cid,current_user()['id'],'balcão',now(),$sub,0,$sub,'Aberta',$obs]);$eid=(int)$pdo->lastInsertId();$is=$pdo->prepare('INSERT INTO encomenda_itens(encomenda_id,produto_id,quantidade,preco_unitario,subtotal) VALUES(?,?,?,?,?)');foreach($items as $i)$is->execute([$eid,...$i]);$pdo->prepare('INSERT INTO encomenda_status_historico(encomenda_id,status_anterior,status_novo,usuario_id,data_hora) VALUES(?,?,?,?,?)')->execute([$eid,null,'Aberta',current_user()['id'],now()]);$pdo->commit();log_action('encomenda','encomendas',$eid,'Criação pelo balcão');flash('success','Encomenda criada com sucesso.');redirect('detalhes.php?id='.$eid);}catch(Throwable $e){$pdo->rollBack();$error='Não foi possível criar a encomenda.';}}}
include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><h1>Nova encomenda</h1><a class="btn secondary" href="index.php">Voltar</a></div><div class="card"><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field col-6"><label>Cliente</label><select name="cliente_id" required><option value="">Selecione</option><?php foreach($clients as $c): ?><option value="<?=$c['id']?>"><?=e($c['nome'])?></option><?php endforeach;?></select></div><div class="field col-12"><label>Observações</label><textarea name="observacoes"></textarea></div></div><h3 style="margin-top:20px">Itens</h3><div id="items"></div><button type="button" class="btn secondary" onclick="addItem()">＋ Adicionar produto</button><div class="form-actions"><button class="btn primary">Criar encomenda</button></div></form></div><script>const PRODUCTS=<?=json_encode($products,JSON_UNESCAPED_UNICODE)?>;function addItem(){const c=document.getElementById('items');const r=document.createElement('div');r.className='form-grid card';r.style.marginBottom='10px';r.innerHTML='<div class="field col-8"><label>Produto</label><select name="produto_id[]">'+PRODUCTS.map(p=>`<option value="${p.id}">${p.nome.replaceAll("'","\\'")} — R$ ${Number(p.preco).toFixed(2).replace('.',',')}</option>`).join('')+'</select></div><div class="field col-3"><label>Quantidade</label><input type="number" min="0.01" step="0.01" name="quantidade[]" value="1"></div><div class="col-1" style="align-self:end"><button type="button" class="btn danger" onclick="this.closest('.card').remove()">×</button></div>';c.appendChild(r)}addItem();</script><?php include __DIR__.'/../../includes/footer.php'; ?>
